import { test, expect } from '@playwright/test';

test.describe('Popover toggle functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://your-application-url.com');
  });

  test('should display popover when button is clicked', async ({ page }) => {
    await page.getByRole('button', { name: 'Toggle Popover' }).click();
    const popover = page.getByRole('dialog', { name: 'Popover Title' });
    await expect(popover).toBeVisible();
  });

  test('should hide popover when button is clicked again', async ({ page }) => {
    await page.getByRole('button', { name: 'Toggle Popover' }).click();
    await page.getByRole('button', { name: 'Toggle Popover' }).click();
    const popover = page.getByRole('dialog', { name: 'Popover Title' });
    await expect(popover).not.toBeVisible();
  });
});
